package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*; import com.citacloud.springboot.contacloud.app.models.*; import com.citacloud.springboot.contacloud.app.repositories.*; import com.citacloud.springboot.contacloud.app.security.*;
import net.sf.jasperreports.engine.*; import net.sf.jasperreports.engine.data.JRMapCollectionDataSource; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.io.*; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.stream.Collectors;
import com.citacloud.springboot.contacloud.app.views.components.PosNumberFormatter;
@Service
public class CierreCajaPdfService {
 private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"); private final CierreCajaService service; private final CierreCajaRepository cierres; private final LocalFileStorageService storage; private volatile JasperReport report;
 public CierreCajaPdfService(CierreCajaService s,CierreCajaRepository c,LocalFileStorageService st){service=s;cierres=c;storage=st;}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('cierres_caja.imprimir')") public ArchivoPdfDto generar(UUID id){var p=TenantContext.principalActual();CierreCajaDto r=service.obtener(id);CierreCaja c=cierres.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),EmpresaContext.requerirEmpresaId()).orElseThrow(()->new RecursoNoEncontradoException("Cierre de caja no encontrado."));byte[] logo=c.getEmpresaLogo()==null?null:storage.load(c.getEmpresaLogo(),5L*1024*1024).orElse(null);Map<String,Object>x=new HashMap<>();x.put("companyName",c.getEmpresaNombre());x.put("companyTaxId",PurchaseOrderPdfService.formatTaxIdentification(c.getEmpresaIdentificacion()));x.put("companyLogo",logo==null?null:new ByteArrayInputStream(logo));x.put("number",r.numero());x.put("shift",r.turno());x.put("cash",r.caja());x.put("branch",r.sucursal());x.put("openedAt",DT.format(r.apertura()));x.put("closedAt",DT.format(r.cierre()));x.put("openedBy",r.abiertoPor());x.put("closedBy",r.cerradoPor());x.put("currency",r.monedaCodigo());x.put("opening",r.fondoInicial());x.put("cashIn",r.totalEntradasEfectivo());x.put("cashOut",r.totalSalidasEfectivo());x.put("expected",r.esperado());x.put("counted",r.contado());x.put("difference",r.diferencia());x.put("result",label(r.resultado()));x.put("notes",r.observacion());x.put("paymentSummary",r.mediosPago().stream().map(m->m.medio().getEtiqueta()+": "+r.monedaCodigo()+" "+PosNumberFormatter.money(m.importe())).collect(Collectors.joining("   |   ")));Collection<Map<String,?>> rows=new ArrayList<>();r.detalles().stream().filter(d->d.cantidad()>0).forEach(d->rows.add(Map.of("denomination",d.denominacion(),"quantity",d.cantidad(),"subtotal",d.subtotal())));try{byte[] out=JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(reporte(),x,new JRMapCollectionDataSource(rows)));return new ArchivoPdfDto("Cierre_"+r.numero()+".pdf",out);}catch(JRException ex){throw new ReglaNegocioException("No fue posible generar el PDF del cierre de caja.",ex);}}
 private JasperReport reporte(){if(report==null)synchronized(this){if(report==null)try(InputStream in=getClass().getResourceAsStream("/reports/cash-close/cash-close.jrxml")){if(in==null)throw new ReglaNegocioException("No se encontró la plantilla del cierre de caja.");report=JasperCompileManager.compileReport(in);}catch(IOException|JRException ex){throw new ReglaNegocioException("No fue posible compilar la plantilla del cierre de caja.",ex);}}return report;}
 private static String label(ResultadoRecuentoCaja r){return switch(r){case BALANCED->"CUADRE CORRECTO";case OVERAGE->"SOBRANTE DE CAJA";case SHORTAGE->"FALTANTE DE CAJA";};}
}
